{
  "lines": [
    {
      "key": "opening",
      "japanese": "あ、ユミだ。",
      "reading": "ア ユミダ",
      "romaji": "A, Yumi da."
    },
    {
      "key": "reply",
      "japanese": "ケンジ？久しぶり！",
      "reading": "ケンジ ヒサシブリ",
      "romaji": "Kenji? Hisashiburi!"
    },
    {
      "key": "surprise_greeting",
      "japanese": "本当！ここで会うなんて、びっくりしたよ。",
      "reading": "ホント ココデ アウナンテ ビックリシタヨ",
      "romaji": "Honto! Koko de au nante, bikkuri shita yo."
    },
    {
      "key": "agreement_surprise",
      "japanese": "うん、私も！元気だった？",
      "reading": "ウン ワタシモ ゲンキダッタ",
      "romaji": "Un, watashi mo! Genki datta?"
    },
    {
      "key": "response_to_greeting",
      "japanese": "元気だよ。ユミは？",
      "reading": "ゲンキダヨ ユミワ",
      "romaji": "Genki da yo. Yumi wa?"
    },
    {
      "key": "response_to_greeting_2",
      "japanese": "私も元気だよ。ありがとう。",
      "reading": "ワタシモ ゲンキダヨ アリガトウ",
      "romaji": "Watashi mo genki da yo. Arigatou."
    },
    {
      "key": "question_about_activity",
      "japanese": "今、何してるの？",
      "reading": "イマ ナニシテルノ",
      "romaji": "Ima, nani shiteru no?"
    },
    {
      "key": "answer_about_activity",
      "japanese": "ちょっと買い物に来たんだ。",
      "reading": "チョット カイモノニ キタンダ",
      "romaji": "Chotto kaimono ni kitan da."
    },
    {
      "key": "question_about_activity_2",
      "japanese": "そうなんだ。何か欲しいものある？",
      "reading": "ソウナンタ ナニカ ホシイモノ アル",
      "romaji": "Sou nan da. Nanika hoshii mono aru?"
    },
    {
      "key": "answer_about_activity_2",
      "japanese": "ううん、特にないかな。見てるだけ。",
      "reading": "ウウン トクニナイカナ ミテルダケ",
      "romaji": "Uun, toku ni nai kana. Miteru dake."
    },
    {
      "key": "question_about_activity_3",
      "japanese": "そっか。私は友達と一緒だよ。",
      "reading": "ソッカ ワタシワ トモダチト イッショダヨ",
      "romaji": "Sokka. Watashi wa tomodachi to issho da yo."
    },
    {
      "key": "question_about_activity_4",
      "japanese": "あ、そうなんだ。じゃあ、またね。",
      "reading": "ア ソウナンタ ジャア マタネ",
      "romaji": "A, sou nan da. Jaa, mata ne."
    },
    {
      "key": "farewell",
      "japanese": "うん、またね！",
      "reading": "ウン マタネ",
      "romaji": "Un, mata ne!"
    }
  ]
}

